-- ----------------------------
-- Table structure for assessment_components
-- ----------------------------
DROP TABLE IF EXISTS `assessment_components`;
CREATE TABLE `assessment_components`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
