  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_schedule_feature`(`schedule_id` ASC, `feature_id` ASC) USING BTREE,
  INDEX `idx_csf_feature`(`feature_id` ASC) USING BTREE,
