INSERT INTO `admission_paths` VALUES (1, 1, 1, 'ZONASI', 'Jalur Zonasi Domisili (50%)', 'Diperuntukkan bagi calon siswa dengan domisili terdekat ke sekolah berdasarkan radius tempat tinggal pada Kartu Keluarga (KK).', 200, 0.00, 100.00, '{\"notes\": \"Domisili wajib berada dalam radius zona sekolah yang ditetapkan.\", \"documents\": [\"Kartu Keluarga (KK) minimal 1 tahun sebelum pendaftaran\", \"KK asli orang tua/wali\", \"Akta kelahiran\", \"Ijazah/SKL SMP/MTs\", \"Rapor semester 1-5\"]}', 1, 1, '2026-09-23', '2026-10-01', NULL, NULL, '2026-09-29 15:10:45', '2026-09-29 15:10:45', NULL);
INSERT INTO `admission_paths` VALUES (2, 1, 1, 'AFIRMASI', 'Jalur Afirmasi / KETM / ABK (20%)', 'Khusus calon peserta didik dari keluarga ekonomi tidak mampu (KETM) dan penyandang disabilitas berprestasi.', 80, 0.00, 100.00, '{\"notes\": \"Verifikasi lapangan dapat dilakukan untuk memvalidasi status KETM.\", \"documents\": [\"Kartu Indonesia Pintar (KIP) / PKH / KKS\", \"Surat Keterangan Tidak Mampu (SKTM) dari desa/kelurahan\", \"Kartu Keluarga (KK)\", \"Akta kelahiran\", \"Surat keterangan disabilitas dari dokter/psikolog (khusus ABK)\"]}', 2, 1, '2026-09-23', '2026-10-01', NULL, NULL, '2026-09-29 15:10:45', '2026-09-29 15:10:45', NULL);
INSERT INTO `admission_paths` VALUES (3, 1, 1, 'PRESTASI', 'Jalur Prestasi Nilai & Kejuaraan (25%)', 'Berdasarkan nilai akumulasi rapor semester 1-5 dan/atau sertifikat penghargaan kejuaraan akademik, olahraga, seni, & keagamaan.', 100, 70.00, 100.00, '{\"notes\": \"Sertifikat kejuaraan bersifat opsional namun menjadi nilai tambah.\", \"criteria\": {\"academic_weight\": 60, \"achievement_weight\": 40}, \"documents\": [\"Rapor semester 1-5 dengan nilai rata-rata minimal 70\", \"Sertifikat kejuaraan minimal tingkat kabupaten/kota\", \"Piagam penghargaan asli\", \"Kartu Keluarga (KK)\", \"Akta kelahiran\"]}', 3, 1, '2026-09-23', '2026-10-01', NULL, NULL, '2026-09-29 15:10:45', '2026-09-29 15:10:45', NULL);
INSERT INTO `admission_paths` VALUES (4, 1, 1, 'PERPINDAHAN', 'Perpindahan Tugas Orang Tua (5%)', 'Bagi calon siswa yang berpindah domisili karena perpindahan tugas kedinasan orang tua/wali dari instansi resmi atau anak guru.', 20, 0.00, 100.00, '{\"notes\": \"Perpindahan tugas maksimal 1 tahun sebelum tanggal pendaftaran.\", \"documents\": [\"Surat keterangan pindah tugas dari instansi/lembaga resmi\", \"SK mutasi orang tua/wali\", \"Kartu Keluarga (KK) terbaru\", \"Akta kelahiran\", \"SK mengajar dari kepala sekolah (khusus anak guru)\"]}', 4, 1, '2026-09-23', '2026-10-01', NULL, NULL, '2026-09-29 15:10:45', '2026-09-29 15:10:45', NULL);
