INSERT INTO `cbt_features` VALUES (1, 'fullscreen_required', 'browser', 'Wajib Fullscreen', 'Keluar dari fullscreen dicatat sebagai pelanggaran', 1, NULL, NULL, 1, 1, '2026-09-29 18:40:30', '2026-09-29 18:40:30', NULL);
