INSERT INTO `cbt_features` VALUES (17, 'randomize_questions', 'exam', 'Acak Urutan Soal', 'Default diambil dari exam_packages.is_randomized', 0, NULL, NULL, 30, 1, '2026-09-29 18:40:30', '2026-09-29 18:40:30', NULL);
