INSERT INTO `report_data_sources` VALUES (1, NULL, 'academic_scores', 'Nilai Pelajaran (Akademik)', 'academic', 'Data rekapitulasi nilai mata pelajaran santri (Nilai Tugas, UTS, UAS, Nilai Akhir, Predikat, dan Deskripsi Capaian Kompetensi).', '[{\"type\": \"number\", \"field\": \"index\", \"label\": \"No\", \"default_align\": \"center\", \"default_width\": \"6%\"}, {\"type\": \"string\", \"field\": \"subject.name\", \"label\": \"Mata Pelajaran\", \"default_align\": \"left\", \"default_width\": \"34%\"}, {\"type\": \"number\", \"field\": \"assignment_score\", \"label\": \"Nilai Tugas\", \"default_align\": \"center\", \"default_width\": \"12%\"}, {\"type\": \"number\", \"field\": \"midterm_score\", \"label\": \"Nilai UTS\", \"default_align\": \"center\", \"default_width\": \"12%\"}, {\"type\": \"number\", \"field\": \"final_score\", \"label\": \"Nilai UAS\", \"default_align\": \"center\", \"default_width\": \"12%\"}, {\"type\": \"number\", \"field\": \"numeric_score\", \"label\": \"Nilai Akhir\", \"default_align\": \"center\", \"default_width\": \"12%\"}, {\"type\": \"string\", \"field\": \"letter\", \"label\": \"Huruf Mutu\", \"default_align\": \"center\", \"default_width\": \"10%\"}, {\"type\": \"string\", \"field\": \"predicate\", \"label\": \"Predikat\", \"default_align\": \"center\", \"default_width\": \"14%\"}, {\"type\": \"string\", \"field\": \"description\", \"label\": \"Capaian Kompetensi\", \"default_align\": \"left\", \"default_width\": \"40%\"}]', '[{\"index\": 1, \"letter\": \"A\", \"subject\": {\"name\": \"Fiqh Ibadah\"}, \"predicate\": \"Jayyid Jiddan\", \"description\": \"Memahami kaidah fiqih ibadah dengan sangat baik.\", \"final_score\": 90, \"midterm_score\": 85, \"numeric_score\": 88, \"assignment_score\": 88}, {\"index\": 2, \"letter\": \"B\", \"subject\": {\"name\": \"Nahwu (Alfiyah)\"}, \"predicate\": \"Jayyid\", \"description\": \"Mampu menganalisis kaidah nahwu dan i\'rab secara tepat.\", \"final_score\": 82, \"midterm_score\": 80, \"numeric_