INSERT INTO `report_templates` VALUES (11, 'Template Rapor Standar Pesantren & Akademik (Salinan)', 'Template resmi pondok pesantren terpadu dengan capaian akademik, sorogan, tahfidz, dan adab santri.', 'combined', NULL, NULL, 'A4', NULL, NULL, 'portrait', 2.00, 2.00, 2.00, 2.50, '{\"version\":\"1.0\",\"page\":{\"size\":\"A4\",\"orientation\":\"portrait\",\"margin\":{\"top\":2,\"right\":2,\"bottom\":2,\"left\":2.5},\"width\":210,\"height\":297,\"background\":\"#ffffff\"},\"globalStyle\":{\"fontFamily\":\"Times New Roman\",\"fontSize\":12,\"color\":\"#000000\",\"lineHeight\":1.4},\"sections\":[{\"type\":\"text\",\"content\":\"YAYASAN PONDOK PESANTREN AL-HIKMAH\\nLAPORAN HASIL BELAJAR SANTRI (RAPOR)\\nTAHUN AJARAN [[ academic_year.start_year ]]\\/[[ academic_year.end_year ]] - SEMESTER [[ academic_year.semester ]]\",\"style\":{\"fontSize\":14,\"fontWeight\":\"bold\",\"textAlign\":\"center\",\"color\":\"#000000\",\"fontFamily\":\"Times New Roman\",\"marginBottom\":15},\"id\":\"sec_seed_1\",\"order\":1},{\"type\":\"keyvalue\",\"fields\":[{\"label\":\"Nama Santri\",\"binding\":\"student.full_name\"},{\"label\":\"NIS \\/ NISN\",\"binding\":\"student.student_number\"},{\"label\":\"Kelas \\/ Tingkat\",\"binding\":\"classroom.name\"},{\"label\":\"Kamar \\/ Asrama\",\"binding\":\"dormitory.name\"}],\"style\":{\"fontSize\":11,\"textAlign\":\"left\",\"color\":\"#000000\",\"fontFamily\":\"Times New Roman\",\"marginBottom\":15},\"id\":\"sec_seed_2\",\"order\":2},{\"type\":\"table\",\"title\":\"A. CAPAIAN KOMPETENSI AKADEMIK\",\"dataSource\":\"academic_scores\",\"columns\":[{\"header\":\"No\",\"field\":\"index\",\"width\":\"6%\",\"align\":\"center\"},{\"header\":\"Mata Pelajaran\",\"field\":\"subject.name\",\"width\":\"34%\",\"align\":\"left\"},{\"header\":\"Tugas\",\"field\":\"assignment_score\",\"width\":\"10%\",\"align\":\"center\"},{\"header\":\"UTS\",\"field\":\"midterm_score\",\"width\":\"10%\",\"align\":\"center\"},{\"header\":\"UAS\",\"field\":\"final_score\",\"width\":\"1